+		Entry{AccountID: "a", AmountCents: -100, Currency: "EUR"},
+		Entry{AccountID: "y", AmountCents: 100, Currency: "EUR"},
+	); err != nil {
+		t.Fatal(err)
+	}
+	if got := l.Balance("a"); got != 200 {
+		t.Fatalf("balance(a) = %d, want 200", got)
+	}
+}

