+	l := &Ledger{}
+	if err := l.Post(
+		Entry{AccountID: "a", AmountCents: 500, Currency: "EUR"},
+		Entry{AccountID: "b", AmountCents: -500, Currency: "EUR"},
+	); err != nil {
+		t.Fatal(err)
+	}
+	if err := l.Post(
+		Entry{AccountID: "a", AmountCents: -200, Currency: "EUR"},
+		Entry{AccountID: "c", AmountCents: 200, Currency: "EUR"},
+	); err != nil {
+		t.Fatal(err)
+	}
